CREATE TABLE IF NOT EXISTS garages(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(100) NOT NULL,type VARCHAR(32) NOT NULL DEFAULT 'public',owner_type VARCHAR(32) NULL,owner_id BIGINT UNSIGNED NULL,slots INT NOT NULL DEFAULT 10,position_json JSON NULL,spawn_json JSON NULL);
CREATE TABLE IF NOT EXISTS garage_vehicles(vehicle_id BIGINT UNSIGNED PRIMARY KEY,garage_id BIGINT UNSIGNED NOT NULL,parked_at DATETIME NOT NULL,INDEX(garage_id),FOREIGN KEY(vehicle_id) REFERENCES character_vehicles(id) ON DELETE CASCADE,FOREIGN KEY(garage_id) REFERENCES garages(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS vehicle_service_history(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,vehicle_id BIGINT UNSIGNED NOT NULL,type VARCHAR(48) NOT NULL,cost BIGINT NOT NULL DEFAULT 0,mileage DOUBLE NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,INDEX(vehicle_id,created_at),FOREIGN KEY(vehicle_id) REFERENCES character_vehicles(id) ON DELETE CASCADE);
